/**
 * The simple chapters (model chapters@1): the heading, a description and the chapters as a list, each with a
 * picture, a short label (a badge), the title and a paragraph. Axes: layout (rows: the picture at the start of
 * each row, a third of it, paired: two columns, the picture under the copy).
 */
import { For, type JSX } from "solid-js";
import { Badge, Block, Container, List, ListItem, Stack, Text, Title } from "../compose";
import { MediaFrame } from "../components/media-frame";
import { cn } from "../utils";
import type { ChapterItem } from "./chapters-simple.types";

export type ChaptersSimpleProps = {
  id: string;
  title: string;
  description?: string;
  items: ChapterItem[];
  level?: 1 | 2 | 3;
  padding?: "compact" | "standard" | "spacious";
  align?: "start" | "center" | "end";
  layout?: "rows" | "paired";
  landmarkLabel?: string;
};

export function ChaptersSimple({
  id,
  title,
  description = "",
  items,
  level = 2,
  padding = "standard",
  align = "center",
  layout = "rows",
  landmarkLabel,
}: ChaptersSimpleProps) {
  const titleId = id + "-title";
  const column =
    (align as string) === "center" ? "center"
    : (align as string) === "end" ? "end"
    : "start";
  const textAlign =
    (align as string) === "center" ? "text-center"
    : (align as string) === "end" ? "text-end"
    : "text-start";
  const itemsAlign =
    (align as string) === "center" ? "items-center"
    : (align as string) === "end" ? "items-end"
    : "items-start";
  const selfAlign =
    (align as string) === "center" ? "self-center"
    : (align as string) === "end" ? "self-end"
    : "";
  const grid = ((layout as string) === "paired") ? "gap-8 md:grid-cols-2" : "gap-8";
  const item =
    (layout as string) === "paired" ? "flex flex-col gap-6"
    : "flex flex-col gap-6 sm:flex-row sm:items-start";
  const pictureClass = ((layout as string) === "paired") ? "order-last" : "sm:w-1/3 sm:shrink-0";
  const ratio = ((layout as string) === "paired") ? "16/9" : "4/3";
  return (
    <Block
      tag="section"
      class={
        (padding as string) === "compact" ? "py-8 lg:py-16"
        : (padding as string) === "spacious" ? "py-24 lg:py-40"
        : "py-16 lg:py-32"
      }
      aria-labelledby={(landmarkLabel ? undefined : titleId)}
      aria-label={landmarkLabel}
      data-slot="chapters-simple"
    >
      <Container class="mx-auto w-full max-w-6xl px-4">
        <Stack gap="12" align="stretch">
          <Stack gap="4" align={column} class={cn("max-w-2xl", selfAlign)}>
            <Title as={level} size="3xl" weight="bold" class={cn("tracking-tight", textAlign)} id={titleId}>
              {title}
            </Title>
            {description ? (
              <Text size="base" class={cn("text-muted-foreground", textAlign)}>
                {description}
              </Text>
            ) : null}
          </Stack>
          <List tag="ul" class={cn("m-0 w-full list-none p-0", cn("grid grid-cols-1", grid))}>
            <For each={items ?? []}>{(c) => (
              <ListItem class={item} data-slot="chapter">
                <MediaFrame alt={c.title} src={c.image} ratio={ratio} class={pictureClass} />
                <Stack gap="2" align="start">
                  <Badge variant="secondary">
                    {c.label}
                  </Badge>
                  <Title as={(level + 1)} size="lg" weight="semibold" class="text-start">
                    {c.title}
                  </Title>
                  {c.description ? (
                    <Text size="base" class={cn("text-muted-foreground", "text-start")}>
                      {c.description}
                    </Text>
                  ) : null}
                </Stack>
              </ListItem>
            )}</For>
          </List>
        </Stack>
      </Container>
    </Block>
  );
}

